"""MCP tools for the Atlas backend.

Structure mirrors the wheel's ``semvec.coding.mcp_server``: plain
``handle_*`` functions carry the logic and are unit-testable without a
transport; ``create_atlas_mcp_server`` wraps them as FastMCP tools.

Tool names use underscores per MCP identifier rules; the specification's
dotted names map 1:1: ``memory.search`` → ``memory_search``,
``memory.forget`` → ``memory_forget``, ``memory.audit`` → ``memory_audit``.

``memory_forget`` deliberately requires an explicit ``reason`` — an
Art. 17 wipe is an audited business action, never a side effect.
"""

from __future__ import annotations

import json
from typing import Any

from pymongo.database import Database

from semvec_atlas.client_metadata import announce
from semvec_atlas.compliance import AtlasForget
from semvec_atlas.firewall import QuarantineVault
from semvec_atlas.guard import TenantScope
from semvec_atlas.retrieval import RetrievalEngine

__all__ = [
    "create_atlas_mcp_server",
    "handle_audit",
    "handle_firewall_status",
    "handle_forget",
    "handle_quarantine_list",
    "handle_quarantine_release",
    "handle_search",
]


def handle_search(
    db: Database,
    scope: TenantScope,
    embedder: Any,
    *,
    query: str,
    k: int = 8,
    force_fallback: bool = False,
) -> str:
    """Hybrid retrieval over the scope's memory items (JSON result)."""
    engine = RetrievalEngine.for_tenant(
        db, scope, embedder=embedder, force_fallback=force_fallback
    )
    hits = engine.search(query, k=k)
    return json.dumps(
        {
            "path": "rankFusion" if engine.uses_rank_fusion else "clientRRF",
            "weights": engine.weights,
            "hits": [
                {
                    "key": h.key,
                    "summary": h.summary,
                    "tier": h.tier,
                    "ns": h.ns,
                    "score": h.score,
                }
                for h in hits
            ],
        }
    )


def handle_forget(
    db: Database,
    scope: TenantScope,
    *,
    reason: str,
    priv_pem: bytes | None = None,
) -> str:
    """Execute an Art. 17 forget for the scope; returns the certificate summary."""
    cert = AtlasForget(db, scope, priv_pem=priv_pem).forget_all(reason=reason)
    return json.dumps(
        {
            "user_id": cert.user_id,
            "event_count": cert.event_count,
            "deleted_at": cert.deleted_at.isoformat(),
            "reason": cert.reason,
            "issuer": cert.issuer,
            "signature_b64": cert.signature_b64,
        }
    )


def handle_audit(
    db: Database, scope: TenantScope, *, pub_pem: bytes | None = None
) -> str:
    """Return the verified deletion-certificate chain (read-only)."""
    chain = AtlasForget(db, scope).audit(pub_pem=pub_pem)
    return json.dumps(
        {
            "user_id": scope.user_id,
            "certificates": [
                {
                    "reason": e.reason,
                    "request_reason": e.request_reason,
                    "issuer": e.issuer,
                    "event_count": e.event_count,
                    "deleted_at": e.deleted_at.isoformat(),
                    "signature_b64": e.signature_b64,
                    "valid": e.valid,
                }
                for e in chain
            ],
        }
    )


def handle_firewall_status(db: Database, scope: TenantScope) -> str:
    """Content-free firewall observability (JSON result).

    Reports the tenant's anchor catalog with provenance (who learned
    what, correlated via ``text_hash`` — never text, never vectors)
    plus the held-quarantine count, so an operator can see the fleet's
    current immunity at a glance.
    """
    tenant_scope = TenantScope(tenant=scope.tenant)
    anchors = [
        {
            "anchor_id": doc["_id"],
            "kind": doc["kind"],
            "agent": (doc.get("provenance") or {}).get("agent"),
            "text_hash": doc.get("text_hash"),
            "created_at": doc["created_at"].isoformat(),
        }
        for doc in db.firewall_anchors.find(
            tenant_scope.filter(), projection={"embedding": False}
        ).sort("created_at", 1)
    ]
    counts: dict[str, int] = {}
    for a in anchors:
        counts[a["kind"]] = counts.get(a["kind"], 0) + 1
    held = db.quarantined_inputs.count_documents(
        scope.filter({"status": "held"})
    )
    return json.dumps(
        {
            "quarantine": {"held": held},
            "anchor_counts": counts,
            "anchors": anchors,
        }
    )


def handle_quarantine_list(db: Database, scope: TenantScope) -> str:
    """Content-free listing of firewall-held inputs (JSON result).

    Never exposes the held text or embedding — preview is redaction-
    capped, correlation runs over the SHA-256 hash.
    """
    entries = QuarantineVault(db, scope).list()
    return json.dumps(
        {
            "entries": [
                {
                    "quarantine_id": e["_id"],
                    "text_preview": e["text_preview"],
                    "text_hash": e["text_hash"],
                    "score": e["score"],
                    "reason": e["reason"],
                    "level": e["level"],
                    "session": e["session"],
                    "turn": e["turn"],
                    "status": e["status"],
                }
                for e in entries
            ]
        }
    )


def handle_quarantine_release(
    db: Database, scope: TenantScope, *, quarantine_id: str, reason: str
) -> str:
    """Release a held input; returns the full text for re-commit.

    A release is an audited human decision (``reason`` is mandatory,
    like ``memory_forget``); the caller re-ingests the returned text
    as a regular turn. Unknown/double releases report an error.
    """
    try:
        doc = QuarantineVault(db, scope).release(quarantine_id, reason=reason)
    except KeyError as exc:
        return json.dumps({"error": str(exc)})
    return json.dumps(
        {
            "quarantine_id": quarantine_id,
            "text": doc["text"],
            "status": "released",
            "release_reason": reason,
        }
    )


def create_atlas_mcp_server(
    db: Database,
    scope: TenantScope,
    *,
    embedder: Any,
    priv_pem: bytes | None = None,
    pub_pem: bytes | None = None,
):
    """Build the FastMCP server exposing the three Atlas memory tools."""
    from fastmcp import FastMCP

    announce(db.client)

    mcp = FastMCP(
        "semvec-atlas",
        instructions=(
            "Semvec Atlas Edition memory tools. memory_search runs hybrid "
            "retrieval; memory_forget executes a signed GDPR Art. 17 wipe "
            "for this agent's memory stream; memory_audit returns the "
            "verified deletion-certificate chain."
        ),
    )

    @mcp.tool()
    def memory_search(query: str, k: int = 8) -> str:
        """Hybrid search (semantic + lexical + recency) over agent memory."""
        return handle_search(db, scope, embedder, query=query, k=k)

    @mcp.tool()
    def memory_forget(reason: str) -> str:
        """GDPR Art. 17: wipe this agent's memory stream, return signed certificate."""
        return handle_forget(db, scope, reason=reason, priv_pem=priv_pem)

    @mcp.tool()
    def memory_audit() -> str:
        """Return the verified deletion-certificate chain for this agent."""
        return handle_audit(db, scope, pub_pem=pub_pem)

    @mcp.tool()
    def memory_quarantine_list() -> str:
        """List firewall-held inputs (content-free: preview + hash only)."""
        return handle_quarantine_list(db, scope)

    @mcp.tool()
    def memory_quarantine_release(quarantine_id: str, reason: str) -> str:
        """Release a held input (audited decision); returns its text for re-commit."""
        return handle_quarantine_release(
            db, scope, quarantine_id=quarantine_id, reason=reason
        )

    @mcp.tool()
    def memory_firewall_status() -> str:
        """Tenant firewall status: anchor catalog with provenance, held count (content-free)."""
        return handle_firewall_status(db, scope)

    return mcp

"""Compatibility suite — CRUD parity with the native LangGraph store.

The same scenario runs against the native ``langgraph-store-mongodb``
``MongoDBStore`` and against ``SemvecStore``; observable CRUD semantics
must match. Search-with-query is intentionally *not* part of the parity
contract (the hybrid path is SemvecStore's added value); namespace
listing and filter-search are.

The native store manages its own collection and TTL indexes, so each
store gets a private collection in the shared test database.
"""

from __future__ import annotations

import pytest

from semvec_atlas.guard import TenantScope
from semvec_atlas.indexes import provision
from semvec_atlas.store import SemvecStore

pytestmark = pytest.mark.mongo


def _native_store(db):
    from langgraph.store.mongodb import MongoDBStore

    return MongoDBStore(collection=db["native_store_items"])


def _semvec_store(db, embedder):
    provision(db, dimension=32, search_indexes=False)
    return SemvecStore(
        db, scope=TenantScope(tenant="acme", agent="compat"), embedder=embedder
    )


@pytest.fixture(params=["native", "semvec"])
def any_store(request, db, embedder):
    if request.param == "native":
        return _native_store(db)
    return _semvec_store(db, embedder)


class TestCrudParity:
    def test_put_get_roundtrip(self, any_store):
        any_store.put(("users", "u1"), "prefs", {"diet": "vegetarian"})
        item = any_store.get(("users", "u1"), "prefs")
        assert item is not None
        assert item.value == {"diet": "vegetarian"}
        assert item.namespace == ("users", "u1")
        assert item.key == "prefs"

    def test_get_missing_returns_none(self, any_store):
        assert any_store.get(("nowhere",), "nope") is None

    def test_overwrite_replaces_value(self, any_store):
        any_store.put(("users", "u1"), "prefs", {"v": 1})
        any_store.put(("users", "u1"), "prefs", {"v": 2})
        assert any_store.get(("users", "u1"), "prefs").value == {"v": 2}

    def test_delete_then_get_returns_none(self, any_store):
        any_store.put(("users", "u1"), "prefs", {"v": 1})
        any_store.delete(("users", "u1"), "prefs")
        assert any_store.get(("users", "u1"), "prefs") is None

    def test_delete_missing_is_noop(self, any_store):
        any_store.delete(("users", "u1"), "ghost")

    def test_search_by_prefix_and_filter(self, any_store):
        any_store.put(("users", "u1"), "a", {"kind": "pref"})
        any_store.put(("users", "u1"), "b", {"kind": "note"})
        any_store.put(("other",), "c", {"kind": "pref"})
        hits = any_store.search(("users",), filter={"kind": "pref"})
        assert [i.key for i in hits] == ["a"]

    def test_list_namespaces_with_prefix(self, any_store):
        any_store.put(("users", "u1"), "a", {"v": 1})
        any_store.put(("kb",), "b", {"v": 2})
        spaces = any_store.list_namespaces(prefix=("users",))
        assert spaces == [("users", "u1")]

"""Mutation-feed integration.

The engine reports per-turn item mutations
(``update(include_mutations=True)`` → ``metrics["mutations"]`` with
kinds ``added``/``promoted``/``demoted``/``merged`` + ``sources``),
verified mirror-grade against the tier enumeration. ``MemoryItemSync``
uses the feed in two ways:

* **fast path** — a turn whose feed reports no mutations skips the
  tier diff entirely (no reads, no writes), except on periodic
  safety-net turns;
* **merge enrichment** — ``merged`` events set ``superseded_by`` on
  the source documents, turning silent displacement into an auditable
  consolidation link.

The tier diff remains the write mechanism (documents are built from
the authoritative tier enumeration); the feed steers *when* it runs
and enriches *why* items disappeared.
"""

from __future__ import annotations

import pytest

from semvec_atlas.commit import TurnCommitter
from semvec_atlas.guard import TenantScope
from semvec_atlas.indexes import provision
from semvec_atlas.item_sync import MemoryItemSync

pytestmark = pytest.mark.mongo


@pytest.fixture()
def scope():
    return TenantScope(tenant="acme", agent="advisor-01")


@pytest.fixture()
def sync(db, scope):
    provision(db, dimension=32, search_indexes=False)
    return MemoryItemSync(db, scope)


class TestFeedFastPath:
    def test_empty_mutations_skips_diff(self, sync, fresh_state, embedder):
        state = fresh_state()
        state.update(embedder.get_embedding("fact"), "fact")
        sync.sync(state, session="s1", turn=1)  # baseline mirror
        # A no-mutation turn must not touch the collection at all.
        report = sync.sync(state, session="s1", turn=2, mutations=[])
        assert (report.added, report.updated, report.evicted) == (0, 0, 0)
        assert report.skipped is True

    def test_nonempty_mutations_runs_diff(self, sync, fresh_state, embedder):
        state = fresh_state()
        state.update(embedder.get_embedding("fact"), "fact")
        report = sync.sync(
            state, session="s1", turn=1,
            mutations=[{"kind": "added", "id": "irrelevant"}],
        )
        assert report.added == 1
        assert report.skipped is False

    def test_none_mutations_means_no_feed_and_runs_diff(self, sync, fresh_state, embedder):
        # Backwards compatibility: callers without feed keep full diffs.
        state = fresh_state()
        state.update(embedder.get_embedding("fact"), "fact")
        report = sync.sync(state, session="s1", turn=1, mutations=None)
        assert report.added == 1 and report.skipped is False

    def test_safety_net_forces_diff_despite_empty_feed(self, sync, fresh_state, embedder):
        state = fresh_state()
        state.update(embedder.get_embedding("fact"), "fact")
        report = sync.sync(
            state, session="s1", turn=1, mutations=[], force_diff=True
        )
        assert report.added == 1 and report.skipped is False


class TestMergeEnrichment:
    def test_merged_sources_get_superseded_by(self, db, scope, mongo_client, embedder, fresh_state):
        # Drive a real engine at tiny capacities until merges occur;
        # committer wires the feed through.
        from semvec import SemvecConfig, SemvecState

        provision(db, dimension=32, search_indexes=False)
        committer = TurnCommitter(
            mongo_client, db, scope, embedder=embedder, snapshot_every=0
        )
        state = SemvecState(
            SemvecConfig(
                dimension=32, short_term_size=3, medium_term_size=3, long_term_size=3
            )
        )
        merged_seen = 0
        for turn in range(1, 41):
            result = committer.run_turn(
                state, session="s1", turn=turn, text=f"pressure fact {turn}"
            )
            merged_seen += sum(
                1 for m in (result.mutations or []) if m["kind"] == "merged"
            )
        assert merged_seen > 0, "engine produced no merges — capacities too large?"

        superseded = list(
            db.memory_items.find(scope.filter({"superseded_by": {"$exists": True}}))
        )
        assert superseded, "merged sources must carry superseded_by"
        # Every superseded_by target must reference an existing live item.
        for doc in superseded:
            target = db.memory_items.find_one(
                scope.filter({"key": doc["superseded_by"]})
            )
            assert target is not None

    def test_mirror_matches_tier_enumeration_after_pressure(
        self, db, scope, mongo_client, embedder
    ):
        from semvec import SemvecConfig, SemvecState

        provision(db, dimension=32, search_indexes=False)
        committer = TurnCommitter(
            mongo_client, db, scope, embedder=embedder, snapshot_every=0
        )
        state = SemvecState(
            SemvecConfig(
                dimension=32, short_term_size=3, medium_term_size=3, long_term_size=3
            )
        )
        for turn in range(1, 41):
            committer.run_turn(state, session="s1", turn=turn, text=f"p {turn}")

        live_engine = {
            u.id
            for tier in (state.memory.short_term, state.memory.medium_term, state.memory.long_term)
            for u in tier
        }
        live_mirror = {
            d["key"]
            for d in db.memory_items.find(
                scope.filter({"deleted": False, "evicted": False, "kind": "engine"})
            )
        }
        assert live_mirror == live_engine


class TestCommitterWiring:
    def test_run_turn_exposes_mutations(self, db, scope, mongo_client, embedder, fresh_state):
        provision(db, dimension=32, search_indexes=False)
        committer = TurnCommitter(mongo_client, db, scope, embedder=embedder)
        state = fresh_state()
        result = committer.run_turn(state, session="s1", turn=1, text="hello")
        assert result.mutations is not None
        assert any(m["kind"] == "added" for m in result.mutations)

"""Embedding providers and the tenant embedder-fingerprint guard.

The Voyage tests run against an injected fake transport — no network,
no API key, no SDK. The guard tests pin the fail-closed contract: a
tenant's persisted embedder identity must match the embedder every
write/read path is constructed with, so a silent model switch cannot
degrade similarity search.
"""

from __future__ import annotations

import numpy as np
import pytest

from semvec_atlas.embedders import (
    EmbedderMismatch,
    VoyageEmbedder,
    embedder_fingerprint,
    ensure_tenant_embedder,
)
from semvec_atlas.guard import TenantScope


class FakeTransport:
    """Records requests; returns configurable embeddings (status, body)."""

    def __init__(self, dimension: int = 4, status: int = 200):
        self.dimension = dimension
        self.status = status
        self.calls: list[dict] = []

    def __call__(self, url: str, headers: dict, payload: dict):
        self.calls.append({"url": url, "headers": headers, "payload": payload})
        if self.status != 200:
            return self.status, {"detail": "rate limited"}
        data = []
        for i, _text in enumerate(payload["input"]):
            # Scaled one-hot at the position of the request index,
            # deliberately NOT normalized and reverse-ordered: the
            # client must sort by index AND L2-normalize, and the
            # direction proves which slot each vector came from.
            vec = [0.0] * self.dimension
            vec[i % self.dimension] = 3.0
            data.append({"embedding": vec, "index": i})
        return 200, {"data": list(reversed(data)), "model": payload["model"]}


@pytest.fixture()
def transport():
    return FakeTransport()


@pytest.fixture()
def voyage(transport, monkeypatch):
    monkeypatch.setenv("VOYAGE_API_KEY", "test-key")
    return VoyageEmbedder("voyage-3.5", transport=transport)


class TestVoyageEmbedder:
    def test_request_carries_model_auth_and_input(self, voyage, transport):
        voyage.get_embedding("hello world")
        call = transport.calls[0]
        assert call["url"].endswith("/embeddings")
        assert call["headers"]["Authorization"] == "Bearer test-key"
        assert call["payload"]["model"] == "voyage-3.5"
        assert call["payload"]["input"] == ["hello world"]

    def test_vectors_come_back_float64_and_l2_normalized(self, voyage):
        vec = voyage.get_embedding("hello")
        assert vec.dtype == np.float64
        assert float(np.linalg.norm(vec)) == pytest.approx(1.0)

    def test_batch_preserves_order_across_chunks(self, monkeypatch):
        monkeypatch.setenv("VOYAGE_API_KEY", "test-key")
        transport = FakeTransport(dimension=4)
        emb = VoyageEmbedder("voyage-3.5", transport=transport, batch_size=2)
        out = emb.get_embeddings([f"t{i}" for i in range(5)])
        assert out.shape == (5, 4)
        assert len(transport.calls) == 3  # 2 + 2 + 1
        assert transport.calls[0]["payload"]["input"] == ["t0", "t1"]
        # The fake one-hot direction encodes the within-chunk index and
        # its responses arrive reversed — row i must still be the
        # normalized one-hot for its own slot (index-based reassembly).
        expected_slots = [0, 1, 0, 1, 0]
        for row, slot in zip(out, expected_slots, strict=True):
            onehot = np.zeros(4)
            onehot[slot] = 1.0
            np.testing.assert_allclose(row, onehot)

    def test_output_dimension_is_sent_and_answers_get_dimension(
        self, transport, monkeypatch
    ):
        monkeypatch.setenv("VOYAGE_API_KEY", "test-key")
        emb = VoyageEmbedder("voyage-3.5", transport=transport, output_dimension=512)
        assert emb.get_dimension() == 512
        assert transport.calls == []  # no probe needed
        emb.get_embedding("x")
        assert transport.calls[0]["payload"]["output_dimension"] == 512

    def test_get_dimension_probes_once_and_caches(self, voyage, transport):
        assert voyage.get_dimension() == 4
        assert voyage.get_dimension() == 4
        assert len(transport.calls) == 1  # probe exactly once

    def test_missing_api_key_raises(self, transport, monkeypatch):
        monkeypatch.delenv("VOYAGE_API_KEY", raising=False)
        with pytest.raises(ValueError, match="VOYAGE_API_KEY"):
            VoyageEmbedder("voyage-3.5", transport=transport)

    def test_http_error_surfaces_status(self, monkeypatch):
        monkeypatch.setenv("VOYAGE_API_KEY", "test-key")
        emb = VoyageEmbedder(
            "voyage-3.5", transport=FakeTransport(status=429)
        )
        with pytest.raises(RuntimeError, match="429"):
            emb.get_embedding("x")

    def test_exposes_model_name(self, voyage):
        assert voyage.model_name == "voyage-3.5"


class _NamedStub:
    """Minimal embedder with an explicit identity, for guard tests."""

    def __init__(self, model_name: str, dimension: int):
        self.model_name = model_name
        self._dim = dimension

    def get_dimension(self) -> int:
        return self._dim

    def get_embedding(self, text: str) -> np.ndarray:
        rng = np.random.default_rng(abs(hash(text)) % (2**32))
        v = rng.standard_normal(self._dim)
        return v / np.linalg.norm(v)


class TestFingerprint:
    def test_model_name_and_dimension(self):
        assert embedder_fingerprint(_NamedStub("voyage-3.5", 1024)) == "voyage-3.5/1024"

    def test_falls_back_to_class_name(self, embedder):
        assert embedder_fingerprint(embedder) == "DeterministicEmbedder/32"


@pytest.mark.mongo
class TestTenantEmbedderGuard:
    @pytest.fixture()
    def scope(self):
        return TenantScope(tenant="acme", agent="advisor-01")

    def test_first_use_registers_the_fingerprint(self, db, scope, embedder):
        fp = ensure_tenant_embedder(db, scope, embedder)
        doc = db.tenants.find_one({"tenant": "acme"})
        assert doc["embedder"]["fingerprint"] == fp == "DeterministicEmbedder/32"
        assert doc["embedder"]["dimension"] == 32

    def test_same_fingerprint_passes(self, db, scope, embedder):
        ensure_tenant_embedder(db, scope, embedder)
        ensure_tenant_embedder(db, scope, embedder)  # must not raise

    def test_model_switch_fails_closed(self, db, scope):
        ensure_tenant_embedder(db, scope, _NamedStub("voyage-3.5", 32))
        with pytest.raises(EmbedderMismatch, match="voyage-3.5/32"):
            ensure_tenant_embedder(db, scope, _NamedStub("voyage-3.5-lite", 32))

    def test_dimension_switch_fails_closed(self, db, scope):
        ensure_tenant_embedder(db, scope, _NamedStub("voyage-3.5", 1024))
        with pytest.raises(EmbedderMismatch):
            ensure_tenant_embedder(db, scope, _NamedStub("voyage-3.5", 512))

    def test_committer_and_retrieval_are_guarded(
        self, mongo_client, db, scope, embedder
    ):
        from semvec_atlas.commit import TurnCommitter
        from semvec_atlas.indexes import provision
        from semvec_atlas.retrieval import RetrievalEngine

        provision(db, dimension=32, search_indexes=False)
        TurnCommitter(mongo_client, db, scope, embedder=embedder, snapshot_every=0)
        assert db.tenants.find_one({"tenant": "acme"})["embedder"]["fingerprint"] == (
            "DeterministicEmbedder/32"
        )
        # Reading with a different embedder identity must fail closed.
        with pytest.raises(EmbedderMismatch):
            RetrievalEngine(db, scope, embedder=_NamedStub("voyage-3.5", 32))
        # The matching embedder passes.
        RetrievalEngine(db, scope, embedder=embedder)
